'use strict';
window.HRFaq={async mount(page){
 const response=await fetch('/api/faq');if(!response.ok)throw Error('無法載入人事常見問題');const data=await response.json(),node=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n};
 const note=node('p','沿用原人事維護中心內容；其中正式密碼、復原與備份功能尚未實作，不代表已啟用。');note.className='configuration-notice';page.append(note);const tools=document.createElement('div');tools.className='toolbar';tools.innerHTML='<label for="faqSearch">搜尋問題／答案</label><input id="faqSearch"><label for="faqCategory">分類</label><select id="faqCategory"><option value="">全部問題</option><option value="account">登入與帳號</option><option value="form">填寫與期別</option><option value="data">資料與連線</option></select><button type="button" id="printFaq" class="secondary">列印維護操作說明</button>';page.append(tools);const list=document.createElement('div');list.id='faqList';page.append(list);const category=id=>['login','password','recovery'].includes(id)?'account':['submit','period'].includes(id)?'form':'data';
 for(const item of data.items){const d=document.createElement('details');d.className='faq-item';d.dataset.category=category(item.id);d.dataset.faq=item.id;d.append(node('summary',item.question));const ol=document.createElement('ol');for(const step of item.steps)ol.append(node('li',step));d.append(ol);list.append(d)}const count=node('p','');count.id='faqCount';page.append(count);function filter(){const text=document.getElementById('faqSearch').value.trim(),type=document.getElementById('faqCategory').value;for(const d of list.children)d.hidden=!!(text&&!d.textContent.includes(text)||type&&d.dataset.category!==type);count.textContent='共 '+[...list.children].filter(d=>!d.hidden).length+' 個問題'}document.getElementById('faqSearch').oninput=e=>{if(!e.isComposing)filter()};document.getElementById('faqSearch').addEventListener('compositionend',filter);document.getElementById('faqCategory').onchange=filter;document.getElementById('printFaq').onclick=()=>window.print();filter();page.dataset.faqSource=data.sourceCommit;
 const maintenance=document.createElement('details');maintenance.className='faq-item';maintenance.append(node('summary','原維護中心狀態說明（尚未串接）'));for(const text of ['Google 試算表連線：尚未串接','Apps Script 服務：尚未串接','最近資料備份：尚未串接','資料寫入異常：尚未串接','自行修改密碼：待建立驗證','忘記密碼信箱重設：待建立驗證','另一位最高管理員解鎖：待建立權限','備份與還原：待建立權限','正式版會記錄登入失敗、解鎖、密碼重設、權限變更、資料更正及備份操作，並限制只有具備適當權限的人員可以查閱。'])maintenance.append(node('p',text));page.append(maintenance);
}};
